/** Readable quantitative reference algorithms for D08-F04 pattern matching. */

const EPSILON = 1e-12;

function series(values: number[], name: string, minimum = 2): number[] {
  if (!Array.isArray(values) || values.length < minimum) throw new Error(`${name} must contain at least ${minimum} values`);
  return values.map((value) => {
    if (typeof value !== "number" || !Number.isFinite(value)) throw new Error(`${name} values must be finite numbers`);
    return value;
  });
}

export function zNormalize(values: number[]): number[] {
  const source = series(values, "values");
  const mean = source.reduce((sum, value) => sum + value, 0) / source.length;
  const variance = source.reduce((sum, value) => sum + (value - mean) ** 2, 0) / source.length;
  if (variance <= EPSILON) throw new Error("z-normalization is undefined for a constant sequence");
  const scale = Math.sqrt(variance);
  return source.map((value) => (value - mean) / scale);
}

const euclidean = (left: number[], right: number[]) => Math.sqrt(left.reduce((sum, value, index) => sum + (value - right[index]) ** 2, 0));

export function normalizedTemplateMatch(valuesInput: number[], templateInput: number[]) {
  const values = series(valuesInput, "series", 3);
  const query = series(templateInput, "template", 3);
  if (query.length > values.length) throw new Error("template cannot be longer than series");
  const normalizedQuery = zNormalize(query);
  const profile: Array<{ start: number; correlation: number | null; distance: number | null; eligible: boolean }> = [];
  for (let start = 0; start <= values.length - query.length; start += 1) {
    try {
      const window = zNormalize(values.slice(start, start + query.length));
      const correlation = normalizedQuery.reduce((sum, value, index) => sum + value * window[index], 0) / query.length;
      profile.push({ start, correlation, distance: euclidean(normalizedQuery, window), eligible: true });
    } catch {
      profile.push({ start, correlation: null, distance: null, eligible: false });
    }
  }
  const eligible = profile.filter((row) => row.eligible).sort((a, b) => (a.distance! - b.distance!) || a.start - b.start);
  if (!eligible.length) throw new Error("series contains no nonconstant eligible window");
  const best = eligible[0];
  return { template_length: query.length, best_start: best.start, best_end: best.start + query.length - 1, correlation: best.correlation, distance: best.distance, profile, normalization: "population-z-score-per-window" };
}

export function dtwDistance(queryInput: number[], candidateInput: number[], radiusInput?: number, normalize = true) {
  const left = series(queryInput, "query");
  const right = series(candidateInput, "candidate");
  const radius = radiusInput ?? Math.max(left.length, right.length);
  if (!Number.isInteger(radius) || radius < Math.abs(left.length - right.length)) throw new Error("radius must be an integer at least the length difference");
  const a = normalize ? zNormalize(left) : left;
  const b = normalize ? zNormalize(right) : right;
  const rows = a.length;
  const cols = b.length;
  const cost = Array.from({ length: rows + 1 }, () => Array(cols + 1).fill(Number.POSITIVE_INFINITY));
  cost[0][0] = 0;
  for (let i = 1; i <= rows; i += 1) {
    for (let j = Math.max(1, i - radius); j <= Math.min(cols, i + radius); j += 1) {
      const local = (a[i - 1] - b[j - 1]) ** 2;
      cost[i][j] = local + Math.min(cost[i - 1][j], cost[i][j - 1], cost[i - 1][j - 1]);
    }
  }
  if (!Number.isFinite(cost[rows][cols])) throw new Error("radius leaves no valid warping path");
  const path: number[][] = [];
  let i = rows;
  let j = cols;
  while (i > 0 || j > 0) {
    path.push([i - 1, j - 1]);
    const options: Array<[number, number, number]> = [];
    if (i > 0 && j > 0) options.push([cost[i - 1][j - 1], i - 1, j - 1]);
    if (i > 0) options.push([cost[i - 1][j], i - 1, j]);
    if (j > 0) options.push([cost[i][j - 1], i, j - 1]);
    options.sort((x, y) => (x[0] - y[0]) || (Math.abs(x[1] - x[2]) - Math.abs(y[1] - y[2])) || (x[1] - y[1]) || (x[2] - y[2]));
    [, i, j] = options[0];
  }
  path.reverse();
  const total = cost[rows][cols];
  return { distance: Math.sqrt(total), path_rms: Math.sqrt(total / path.length), path_length: path.length, path, radius, normalized: normalize, cost_matrix: cost.slice(1).map((row) => row.slice(1).map((value) => Number.isFinite(value) ? value : null)) };
}

export function matrixProfile(seriesInput: number[], window: number, exclusionZone?: number) {
  const values = series(seriesInput, "series", 6);
  if (!Number.isInteger(window) || window < 3 || window > Math.floor(values.length / 2)) throw new Error("window must be an integer from 3 through half the series length");
  const zone = exclusionZone ?? Math.ceil(window / 2);
  if (!Number.isInteger(zone) || zone < 0) throw new Error("exclusion_zone must be a nonnegative integer");
  const subsequences: Array<number[] | null> = [];
  for (let start = 0; start <= values.length - window; start += 1) {
    try { subsequences.push(zNormalize(values.slice(start, start + window))); } catch { subsequences.push(null); }
  }
  const profile: Array<number | null> = Array(subsequences.length).fill(null);
  const indexes: Array<number | null> = Array(subsequences.length).fill(null);
  for (let i = 0; i < subsequences.length; i += 1) {
    const left = subsequences[i];
    if (!left) continue;
    let bestDistance = Number.POSITIVE_INFINITY;
    let bestIndex: number | null = null;
    for (let k = 0; k < subsequences.length; k += 1) {
      const right = subsequences[k];
      if (!right || Math.abs(i - k) <= zone) continue;
      const distance = euclidean(left, right);
      if (distance < bestDistance - EPSILON || (Math.abs(distance - bestDistance) <= EPSILON && (bestIndex === null || k < bestIndex))) {
        bestDistance = distance;
        bestIndex = k;
      }
    }
    if (bestIndex !== null) { profile[i] = bestDistance; indexes[i] = bestIndex; }
  }
  const eligible = profile.map((distance, index) => [distance, index, indexes[index]] as const).filter((row) => row[0] !== null && row[2] !== null).sort((a, b) => (a[0]! - b[0]!) || (a[1] - b[1]) || (a[2]! - b[2]!));
  if (!eligible.length) throw new Error("no eligible nontrivial subsequence pair");
  const [distance, first, second] = eligible[0];
  return { window, exclusion_zone: zone, profile, profile_index: indexes, motif_pair: [first, second!].sort((a, b) => a - b), motif_distance: distance, normalization: "population-z-score-per-subsequence" };
}

export function shapeletDistance(seriesInput: number[], shapeletInput: number[]) {
  const values = series(seriesInput, "series", 3);
  const shapelet = series(shapeletInput, "shapelet");
  if (shapelet.length > values.length) throw new Error("shapelet cannot be longer than series");
  const normalizedShapelet = zNormalize(shapelet);
  const profile: Array<number | null> = [];
  for (let start = 0; start <= values.length - shapelet.length; start += 1) {
    try { profile.push(euclidean(normalizedShapelet, zNormalize(values.slice(start, start + shapelet.length)))); } catch { profile.push(null); }
  }
  const eligible = profile.map((distance, index) => [distance, index] as const).filter((row) => row[0] !== null).sort((a, b) => (a[0]! - b[0]!) || a[1] - b[1]);
  if (!eligible.length) throw new Error("series contains no eligible nonconstant window");
  return { distance: eligible[0][0]!, best_start: eligible[0][1], profile };
}

function entropy(labels: boolean[]): number {
  if (!labels.length) return 0;
  const proportion = labels.filter(Boolean).length / labels.length;
  if (proportion === 0 || proportion === 1) return 0;
  return -proportion * Math.log2(proportion) - (1 - proportion) * Math.log2(1 - proportion);
}

export function trainShapeletThreshold(trainingSeries: number[][], labels: boolean[], shapelet: number[]) {
  if (!Array.isArray(trainingSeries) || trainingSeries.length < 2 || trainingSeries.length !== labels.length) throw new Error("series and labels must have the same length of at least 2");
  if (labels.some((label) => typeof label !== "boolean") || new Set(labels).size < 2) throw new Error("labels must be booleans containing both classes");
  const distances = trainingSeries.map((item) => shapeletDistance(item, shapelet).distance);
  const unique = [...new Set(distances)].sort((a, b) => a - b);
  const thresholds = unique.slice(0, -1).map((value, index) => (value + unique[index + 1]) / 2);
  if (!thresholds.length) throw new Error("training distances do not define a split");
  const parent = entropy(labels);
  const rows = thresholds.map((threshold) => {
    const below = labels.filter((_, index) => distances[index] <= threshold);
    const above = labels.filter((_, index) => distances[index] > threshold);
    const information_gain = parent - (below.length / labels.length) * entropy(below) - (above.length / labels.length) * entropy(above);
    const below_label = below.filter(Boolean).length >= below.length / 2;
    const predicted = distances.map((distance) => distance <= threshold ? below_label : !below_label);
    const training_accuracy = predicted.filter((guess, index) => guess === labels[index]).length / labels.length;
    return { threshold, information_gain, below_label, training_accuracy };
  }).sort((a, b) => (b.information_gain - a.information_gain) || (b.training_accuracy - a.training_accuracy) || (a.threshold - b.threshold));
  return { ...rows[0], distances, shapelet_length: shapelet.length };
}

export function classifyShapelet(seriesInput: number[], shapelet: number[], threshold: number, belowLabel = true) {
  if (!Number.isFinite(threshold) || threshold < 0) throw new Error("threshold must be a finite nonnegative number");
  const result = shapeletDistance(seriesInput, shapelet);
  const matched = result.distance <= threshold;
  return { ...result, threshold, matched, predicted_label: matched ? belowLabel : !belowLabel };
}
